function readForm(){
  const f=$("#survey"),a={};
  for(const q of Q){ if(!q.id)continue;
    if(q.t==="checks") a[q.id]=[...f.querySelectorAll(`input[name="${q.id}"]:checked`)].map(i=>i.value);
    else if(q.t==="radio"){const c=f.querySelector(`input[name="${q.id}"]:checked`);a[q.id]=c?c.value:"";}
    else if(q.t==="consent") a[q.id]=f.querySelector(`#f-consent`).checked;
    else a[q.id]=(f.querySelector(`#f-${q.id}`)?.value||"").trim();
  } return a;
}
function renderForm(){
  const prev=document.querySelector("#survey").children.length?readForm():(store.get("askmi-draft")||{});
  const L=lang, ix=L==="de"?1:2; let html="", open=false, n=0;
  for(const q of Q){
    if(q.sec){ if(open) html+="</fieldset></div>"; html+=`<div class="card"><fieldset><legend>${esc(q[L])}</legend>`; open=true; continue; }
    const [lab,hint]=q[L]; const v=prev[q.id]; const num=q.t==="consent"?"":`${++n}. `;
    const star=q.req?'<span class="req" aria-hidden="true">*</span>':"";
    html+=`<div class="q" data-q="${q.id}">`;
    if(q.t==="consent"){ html+=`<div class="opts"><label><input type="checkbox" id="f-consent" ${v?"checked":""} aria-required="true"> <span>${esc(lab)}${star}</span></label></div>`; }
    else{
      html+=`<label class="ql" ${["text","textarea","select"].includes(q.t)?`for="f-${q.id}"`:""} id="lab-${q.id}">${num}${esc(lab)}${star}</label>`;
      if(hint) html+=`<span class="hint">${esc(hint)}</span>`;
      if(q.t==="text") html+=`<input type="text" id="f-${q.id}" value="${esc(v||"")}" maxlength="300">`;
      if(q.t==="textarea") html+=`<textarea id="f-${q.id}" maxlength="2000">${esc(v||"")}</textarea>`;
      if(q.t==="select") html+=`<select id="f-${q.id}">${q.o.map(o=>`<option value="${o[0]}" ${v===o[0]?"selected":""}>${esc(o[ix])}</option>`).join("")}</select>`;
      if(q.t==="radio"||q.t==="checks"){ const ty=q.t==="radio"?"radio":"checkbox";
        html+=`<div class="opts" role="${q.t==="radio"?"radiogroup":"group"}" aria-labelledby="lab-${q.id}">`+q.o.map(o=>{const on=q.t==="radio"?v===o[0]:(Array.isArray(v)&&v.includes(o[0]));return `<label><input type="${ty}" id="f-${q.id}-${o[0]}" name="${q.id}" value="${o[0]}" ${on?"checked":""}> <span>${esc(o[ix])}</span></label>`}).join("")+"</div>"; }
    }
    html+=`<span class="err" hidden></span></div>`;
  }
  if(open) html+="</fieldset></div>";
  html+=`<div class="row"><button class="btn" type="submit">${UI[L].submit}</button><span class="err" id="f-err" role="alert"></span></div>`;
  $("#survey").innerHTML=html;
  const u=UI[L]; $("#h-title").textContent=u.title; $("#h-lede").textContent=u.lede; $("#s-privacy").textContent=u.privacy;
  $("#r-title").textContent=u.rt; $("#r-text").textContent=u.rx; $("#copy").textContent=u.copy; $("#edit").textContent=u.edit; $("#t-survey").textContent=u.tab;
  document.documentElement.lang=L;
}
