function missing(a){return Q.filter(q=>q.id&&q.req).filter(q=>{const v=a[q.id];return Array.isArray(v)?!v.length:!v}).map(q=>q.id);}
function ref(){const c="REDACTED",b=new Uint8Array(6);crypto.getRandomValues(b);return "S-"+[...b].map(x=>c[x%c.length]).join("");}
$("#survey").addEventListener("submit",e=>{
  e.preventDefault(); const a=readForm(), m=missing(a);
  document.querySelectorAll(".q .err").forEach(el=>el.hidden=true);
  if(m.length){ m.forEach(id=>{const el=document.querySelector(`[data-q="${id}"] .err`);el.textContent="✕";el.hidden=false;}); $("#f-err").textContent=UI[lang].missing; document.querySelector(`[data-q="${m[0]}"]`).scrollIntoView({block:"center"}); return; }
  $("#f-err").textContent="";
