function copyFrom(el,status){const t=el.textContent;const sel=()=>{const r=document.createRange();r.selectNodeContents(el);const s=getSelection();s.removeAllRanges();s.addRange(r);};
  try{navigator.clipboard.writeText(t).then(()=>{status&&(status.textContent=UI[lang].copied)},()=>{sel();status&&(status.textContent=UI[lang].sel)});}catch(e){sel();status&&(status.textContent=UI[lang].sel);}}
$("#copy").onclick=()=>copyFrom($("#out"),$("#copied"));

