// ---------- Owner tally ----------
const TARGET={done:20,conf:8,buyer:3};
const lbl=(id,val)=>{const q=Q.find(x=>x.id===id);const o=q&&q.o&&q.o.find(x=>x[0]===val);return o?o[1]:val;};
const filled=s=>typeof s==="string"&&s.trim().length>=3;
function assess(a,ev){
  const hasCurrent=(a.current||[]).length>0;
  const cons=(a.conseq||[]).filter(c=>c!=="none");
  const problem=filled(a.problem)&&a.problem.trim().length>=20;
  const confirm=problem&&hasCurrent&&cons.length>0?"yes":"unclear";
  const unk=/^(weiß|weiss|keine?|kein termin|no |none|don.?t know|unklar|n\/?a|-)/i;
  const budget=filled(a.budgetOwner)&&!unk.test(a.budgetOwner.trim());
  const trig=a.trigger&&!["none","unknown",""].includes(a.trigger);
  const dl=filled(a.deadline)&&!unk.test(a.deadline.trim());
  const complete=filled(a.role)&&!!a.cohort&&filled(a.workflow)&&hasCurrent&&problem&&(a.conseq||[]).length>0&&!!a.budgetOwner&&!!a.trigger&&!!a.deadline&&filled(ev);
  return {confirm,budget,trig,dl,buyer:budget||trig||dl?"yes":"no",complete};
}
const CP={hosp:"HOSP",int:"INT",idps:"ID",other:"OTH"};
let db=null, rows=[];
function pill(v){return v==="yes"?'<span class="pill yes">Yes</span>':v==="no"?'<span class="pill no">No</span>':'<span class="pill unc">Unclear</span>';}
function eff(r){return {complete:r.override?.complete??r.auto.complete, confirm:r.override?.confirm??r.auto.confirm, buyer:r.override?.buyer??r.auto.buyer};}
function renderTally(){
  const E=rows.map(r=>({r,e:eff(r)})); const done=E.filter(x=>x.e.complete);
  const conf=done.filter(x=>x.e.confirm==="yes").length, buy=done.filter(x=>x.e.buyer==="yes").length;
  const orgs=new Set(done.map(x=>x.r.org).filter(Boolean)).size;
  const g=(name,v,t)=>`<div class="gauge"><span class="eyebrow">${name}</span><b>${v} <span class="small">/ ${t}</span></b><div class="bar"><i class="${v>=t?"done":""}" style="width:${Math.min(100,v/t*100)}%"></i></div></div>`;
  $("#gauges").innerHTML=g("Abgeschlossen",done.length,TARGET.done)+g("Problembestätigungen",conf,TARGET.conf)+g("Buyer-Signale",buy,TARGET.buyer)+`<div class="gauge"><span class="eyebrow">Organisationen</span><b>${orgs}</b><span class="small">eindeutig, mit Pseudonym</span></div>`;
  $("#list").innerHTML=rows.length?rows.map(r=>{const e=eff(r),a=r.answers;return `<div class="resp" data-id="${esc(r.id)}">
    <div class="row" style="justify-content:space-between"><strong class="mono">${esc(r.id)}</strong><span class="small">${esc(r.date)} · ${esc(lbl("cohort",a.cohort))} · ${esc(a.role)} · ${esc(lbl("market",a.market))}${r.org?" · "+esc(r.org):""}</span></div>
    <p class="small"><strong>Problem:</strong> ${esc(a.problem)}</p>
    <div class="grid">
      <label class="small">Abgeschlossen<select data-k="complete"><option value="true" ${e.complete?"selected":""}>Ja</option><option value="false" ${!e.complete?"selected":""}>Nein</option></select></label>
      <label class="small">Problembestätigung<select data-k="confirm">${["yes","no","unclear"].map(v=>`<option value="${v}" ${e.confirm===v?"selected":""}>${v}</option>`).join("")}</select></label>
      <label class="small">Buyer-Signal<select data-k="buyer">${["yes","no"].map(v=>`<option value="${v}" ${e.buyer===v?"selected":""}>${v}</option>`).join("")}</select></label>
      <span class="small">Vorschlag: ${pill(r.auto.confirm)} ${pill(r.auto.buyer)}<br>Budget ${r.auto.budget?"✓":"–"} · Trigger ${r.auto.trig?"✓":"–"} · Deadline ${r.auto.dl?"✓":"–"} · Preis: ${esc(lbl("price",a.price))}</span>
    </div>
    <div class="row"><button class="btn ghost" type="button" data-del>Löschen</button><span class="small">Evidenz: ${esc(r.ev)}</span></div>
  </div>`}).join(""):`<div class="card small">Noch keine Antworten. Wenn ein Befragter seinen Antwortblock zurückschickt, füge ihn oben ein.</div>`;
  $("#rep").textContent=report(E,done,conf,buy,orgs);
}
function report(E,done,conf,buy,orgs){
  const d=new Date().toISOString().slice(0,10);
  const coh=[["hosp","Hospitality/service operators"],["int","Integrators/service platforms"],["idps","Identity/privacy/security owners"],["other","Other"]];
  const t=coh.map(([k,n])=>{const s=done.filter(x=>x.r.answers.cohort===k);return `| ${n} | ${s.length} | ${s.filter(x=>x.e.confirm==="yes").length} | ${s.filter(x=>x.e.buyer==="yes").length} |`}).join("\n");
  const pass=done.length>=20&&conf>=8&&buy>=3;
  const prices={};done.forEach(x=>{const p=x.r.answers.price;prices[p]=(prices[p]||0)+1});
  return `## G1 buyer-gate decision — ${d}

### Counts

- Completed interviews: ${done.length} / 20
- Unique organisations: ${orgs}
- Problem confirmations: ${conf} / 8
- Buyer/procurement/deadline signals: ${buy} / 3

### Cohort mix

| Cohort | Interviews | Confirmations | Buyer signals |
|---|---:|---:|---:|
${t}

### Repeated evidence

- Confirmed problem:
- Current workaround:
- Consequence:
- Economic buyer:
- Technical champion:
- Procurement trigger/deadline:
- Selected hospitality workflow:
- Price/procurement finding: ${Object.entries(prices).map(([k,v])=>`${k} ${v}`).join(", ")||"—"}
- Strongest contrary evidence:

### Decision

- [${pass?"x":" "}] PASS — all three G1 thresholds have qualifying evidence.
- [${pass?" ":"x"}] MISS — at least one threshold lacks qualifying evidence.

If missed: pause broad product expansion and revise the buyer, workflow, or category hypothesis.

### Evidence handling

Private notes remain outside the public repository. Public entries contain anonymised counts and approved findings only.`;
}
$("#rep-copy").onclick=()=>copyFrom($("#rep"),null);
$("#imp-go").onclick=async()=>{
  const err=$("#imp-err"); err.textContent="";
  let o; try{o=JSON.parse($("#imp").value.trim())}catch(e){err.textContent="Kein gültiger Antwortblock. Bitte den ganzen Block inklusive geschweifter Klammern einfügen.";return;}
  if(o.v!=="askmi-g1-survey/1"||!o.answers){err.textContent="Unbekanntes Format. Erwartet wird askmi-g1-survey/1.";return;}
  if(!o.answers.consent){err.textContent="Ohne Einwilligung nicht importieren.";return;}
  if(rows.some(r=>r.ref===o.ref)){err.textContent=`Antwort ${o.ref} ist schon importiert.`;return;}
  const ev=$("#imp-ev").value.trim(); if(!ev){err.textContent="Bitte einen privaten Evidenz-Verweis angeben (Pflichtfeld nach §10).";return;}
  const p=CP[o.answers.cohort]||"OTH"; const n=rows.filter(r=>r.id.startsWith("G1-"+p+"-")).length+1;
  const id=`G1-${p}-${String(n).padStart(2,"0")}`;
  const rec={id,ref:o.ref,date:o.date,lang:o.lang,org:$("#imp-org").value.trim(),ev,answers:o.answers,auto:assess(o.answers,ev),override:null,importedAt:new Date().toISOString().slice(0,10)};
  try{await db.collection("responses").doc(id).set(rec); $("#imp").value="";$("#imp-org").value="";$("#imp-ev").value="";}
  catch(e){err.textContent="Speichern fehlgeschlagen: "+(e.code||e.message);}
};
$("#list").addEventListener("change",async e=>{
  const s=e.target.closest("select"); if(!s)return; const id=s.closest(".resp").dataset.id; const r=rows.find(x=>x.id===id); if(!r)return;
  const ov={...(r.override||{})}; ov[s.dataset.k]=s.dataset.k==="complete"?s.value==="true":s.value;
  try{await db.collection("responses").doc(id).update({override:ov})}catch(err){$("#imp-err").textContent="Ändern fehlgeschlagen: "+(err.code||err.message);}
});
const pendingDel=new Set();
$("#list").addEventListener("click",async e=>{
  const b=e.target.closest("[data-del]"); if(!b)return; const id=b.closest(".resp").dataset.id;
  if(!pendingDel.has(id)){pendingDel.add(id);b.textContent="Wirklich löschen?";setTimeout(()=>{pendingDel.delete(id);b.textContent="Löschen"},4000);return;}
  try{await db.collection("responses").doc(id).delete()}catch(err){$("#imp-err").textContent="Löschen fehlgeschlagen.";}
});

// ---------- boot ----------
renderForm();
(async()=>{
  if(!window.claude?.use) return;
  const user=await claude.use("user"); const owner=await (user?.isOwner?.()??false);
  if(!owner) return;
  db=await claude.use("db"); if(!db) return;
  $("#t-tally").hidden=false; renderTally();
  if(store.get("askmi-tab")==="tally") tab("tally");
  db.collection("responses").onSnapshot(snap=>{rows=snap.docs.map(d=>d.data()).sort((a,b)=>a.id.localeCompare(b.id));renderTally();},e=>{$("#imp-err").textContent="Verbindung zur Auswertung verloren: "+(e.code||"")});
})();
})();
