    font-size: 16px;
    color: #0f172a;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 800;
}

.demo-primary-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-bottom: 12px;
}

.btn-demo-primary {
    padding: 14px 12px;
    border-radius: 10px;
    border: 1px solid rgba(14, 165, 233, 0.2);
    color: #0f172a;
    font-size: 13px;
    font-weight: 700;
