import { describe, expect, it } from 'vitest';
import { identityChallenge, type IdentityAssertion } from '@askmi/shared-crypto';
import {
  createProofToken,
  decodeProofTokenHeader,
  verifyProofToken,
  type ProofTokenSigner,
} from '../utils/proof-token';

const enc = new TextEncoder();
const b64url = (bytes: Uint8Array) =>
  btoa(String.fromCharCode(...bytes))
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
const sha256 = async (bytes: Uint8Array<ArrayBuffer>) =>
  new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));

async function p256() {
  const keys = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, [
    'sign',
    'verify',
  ]);
  return { keys, jwk: await crypto.subtle.exportKey('jwk', keys.publicKey) };
}

function p1363ToDer(sig: Uint8Array): Uint8Array {
  const int = (b: Uint8Array) => {
    let i = 0;
    while (i < b.length - 1 && b[i] === 0) i++;
    let v = b.slice(i);
    if (v[0] & 0x80) v = Uint8Array.of(0, ...v);
    return Uint8Array.of(0x02, v.length, ...v);
  };
  const r = int(sig.slice(0, 32));
  const s = int(sig.slice(32));
  return Uint8Array.of(0x30, r.length + s.length, ...r, ...s);
}

/** Software signer: raw P-256 ECDSA (P1363), like the wallet's session identity key. */
async function softwareSigner() {
  const { keys } = await p256();
  const signer: ProofTokenSigner = {
    key: 'software-session',
    kid: 'did:askmi:user-wallet-001#software-identity-key',
    sign: async (input) =>
      new Uint8Array(
        await crypto.subtle.sign(
          { name: 'ECDSA', hash: 'SHA-256' },
          keys.privateKey,
          enc.encode(input)
        )
      ),
  };
  return { signer, publicKey: keys.publicKey };
}

/** Hardware signer: a simulated passkey answering like navigator.credentials.get. */
async function passkeySigner(rpId = 'wallet.example') {
  const { keys, jwk } = await p256();
  const signer: ProofTokenSigner = {
    key: 'hardware-passkey',
    kid: 'did:askmi:user-wallet-001#passkey-identity-key',
    sign: async (input): Promise<IdentityAssertion> => {
      const clientDataJSON = enc.encode(
        JSON.stringify({
          type: 'webauthn.get',
          challenge: b64url(new Uint8Array(await identityChallenge(input))),
          origin: 'https://wallet.example',
        })
      );
      const authenticatorData = new Uint8Array(37);
      authenticatorData.set(await sha256(enc.encode(rpId)), 0);
      authenticatorData[32] = 0x05;
      const signed = new Uint8Array([...authenticatorData, ...(await sha256(clientDataJSON))]);
      const sig = new Uint8Array(
        await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, keys.privateKey, signed)
      );
      return {
        version: 1,
        credentialId: 'cred-1',
        rpId,
        authenticatorData: b64url(authenticatorData),
        clientDataJSON: b64url(clientDataJSON),
        signature: b64url(p1363ToDer(sig)),
      };
    },
  };
  return { signer, jwk };
}

const PAYLOAD = { type: 'ProofOfExistence', hash: 'abc123', hashAlg: 'SHA-256' };

/** Replace one dot-separated part of a token. */
const withPart = (token: string, index: number, value: string) =>
  token
    .split('.')
    .map((p, i) => (i === index ? value : p))
    .join('.');

describe('proof tokens: software session key', () => {
  it('labels the token and verifies with the session public key', async () => {
    const { signer, publicKey } = await softwareSigner();
    const token = await createProofToken(PAYLOAD, signer);

    expect(token.split('.')).toHaveLength(3);
    expect(decodeProofTokenHeader(token)).toEqual({
      typ: 'askmi-poe',
      v: 2,
      alg: 'ES256',
      key: 'software-session',
      kid: 'did:askmi:user-wallet-001#software-identity-key',
      enc: 'base64url',
    });
    const result = await verifyProofToken(token, { softwarePublicKey: publicKey });
    expect(result).toEqual({ valid: true, header: decodeProofTokenHeader(token), payload: PAYLOAD });
  });

  it('rejects a changed payload', async () => {
    const { signer, publicKey } = await softwareSigner();
    const token = await createProofToken(PAYLOAD, signer);
    const forged = withPart(token, 1, b64url(enc.encode(JSON.stringify({ ...PAYLOAD, hash: 'x' }))));
    expect(await verifyProofToken(forged, { softwarePublicKey: publicKey })).toEqual({
      valid: false,
      reason: 'BAD_SIGNATURE',
    });
  });

  it('covers the header too: a changed kid breaks the signature', async () => {
    const { signer, publicKey } = await softwareSigner();
    const token = await createProofToken(PAYLOAD, signer);
    const header = { ...decodeProofTokenHeader(token)!, kid: 'did:askmi:someone-else#key' };
    const forged = withPart(token, 0, b64url(enc.encode(JSON.stringify(header))));
    expect(await verifyProofToken(forged, { softwarePublicKey: publicKey })).toEqual({
      valid: false,
      reason: 'BAD_SIGNATURE',
    });
  });

  it('reports NO_PUBLIC_KEY when no session key is given', async () => {
    const { signer } = await softwareSigner();
    const token = await createProofToken(PAYLOAD, signer);
    expect(await verifyProofToken(token, {})).toEqual({ valid: false, reason: 'NO_PUBLIC_KEY' });
  });
});

describe('proof tokens: hardware passkey', () => {
  it('labels the token and verifies against the stored passkey public key', async () => {
    const { signer, jwk } = await passkeySigner();
    const token = await createProofToken(PAYLOAD, signer);

    expect(decodeProofTokenHeader(token)).toMatchObject({
      alg: 'webauthn-es256',
      key: 'hardware-passkey',
      enc: 'base64url',
    });
    const result = await verifyProofToken(token, {
      publicKeyJwk: jwk,
      expectedRpId: 'wallet.example',
      expectedOrigin: 'https://wallet.example',
    });
    expect(result).toMatchObject({ valid: true, payload: PAYLOAD });
  });

  it('rejects a changed payload (challenge no longer matches)', async () => {
    const { signer, jwk } = await passkeySigner();
    const token = await createProofToken(PAYLOAD, signer);
    const forged = withPart(token, 1, b64url(enc.encode(JSON.stringify({ ...PAYLOAD, hash: 'x' }))));
    expect(
      await verifyProofToken(forged, { publicKeyJwk: jwk, expectedRpId: 'wallet.example' })
    ).toEqual({ valid: false, reason: 'CHALLENGE_MISMATCH' });
  });

  it('rejects a token signed by a different passkey', async () => {
    const { signer } = await passkeySigner();
    const other = await passkeySigner();
    const token = await createProofToken(PAYLOAD, signer);
    expect(
      await verifyProofToken(token, { publicKeyJwk: other.jwk, expectedRpId: 'wallet.example' })
    ).toEqual({ valid: false, reason: 'BAD_SIGNATURE' });
  });

  it('cannot be checked without the stored public key or the expected rpId', async () => {
    const { signer, jwk } = await passkeySigner();
    const token = await createProofToken(PAYLOAD, signer);
    expect(await verifyProofToken(token, { expectedRpId: 'wallet.example' })).toEqual({
      valid: false,
      reason: 'NO_PUBLIC_KEY',
    });
    expect(await verifyProofToken(token, { publicKeyJwk: jwk })).toEqual({
      valid: false,
      reason: 'NO_EXPECTED_RP_ID',
    });
  });
});

describe('proof tokens: malformed and legacy input', () => {
  it('rejects the old unlabelled v1 format (ES256-PoC, hex signature)', async () => {
    const legacy = `${btoa('{"alg":"ES256-PoC","kid":"x"}')}.${btoa('{}')}.${'ab'.repeat(64)}`;
    expect(await verifyProofToken(legacy, {})).toEqual({
      valid: false,
      reason: 'UNSUPPORTED_FORMAT',
    });
  });

  it('reports MALFORMED instead of throwing on garbage', async () => {
    for (const bad of ['', 'a.b', 'a.b.c.d', '!!.??.**']) {
      expect(await verifyProofToken(bad, {})).toEqual({ valid: false, reason: 'MALFORMED' });
    }
  });
});

import {
  canonicalStringify,
  isUsableP256Jwk,
  verifyIdentityAssertion,
  type AssertionFailure,
  type IdentityAssertion,
} from '@askmi/shared-crypto';

/**
 * Signed proof tokens for wallet-initiated requests (erasure, verifier reports,
 * document proofs).
 *
 * Format v2: base64url(header) . base64url(payload) . base64url(signature part)
 * The signature covers "header.payload", so the labels can't be swapped.
 *
 * - key "hardware-passkey", alg "webauthn-es256": the signature part is the full
 *   WebAuthn assertion (JSON), checkable with the passkey public key saved at
 *   registration (verifyIdentityAssertion).
 * - key "software-session", alg "ES256": the signature part is a raw P-256 ECDSA
 *   signature (r||s) from the wallet's software identity key, used only where
 *   WebAuthn is unavailable. Only the session public key can check it.
 *
 * Not RFC 7515 JWS: the hardware variant has no JWS equivalent.
 */

export type ProofTokenKey = 'hardware-passkey' | 'software-session';

export interface ProofTokenHeader {
  typ: 'askmi-poe';
  v: 2;
  alg: 'webauthn-es256' | 'ES256';
  key: ProofTokenKey;
  kid: string;
  enc: 'base64url';
}

export type ProofTokenSigner =
  | {
      key: 'hardware-passkey';
      kid: string;
      sign: (signingInput: string) => Promise<IdentityAssertion>;
    }
  | {
      key: 'software-session';
      kid: string;
      /** raw P-256 ECDSA signature (64 bytes, r||s) over the UTF-8 signing input */
      sign: (signingInput: string) => Promise<Uint8Array>;
    };

export type ProofTokenFailure =
  | AssertionFailure
  | 'UNSUPPORTED_FORMAT'
  | 'NO_EXPECTED_RP_ID';

export type ProofTokenVerification =
  | { valid: true; header: ProofTokenHeader; payload: unknown }
  | { valid: false; reason: ProofTokenFailure };

const utf8 = new TextEncoder();

function toBase64url(bytes: Uint8Array): string {
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

/** Accepts base64url (and, for reading legacy headers, standard base64). Throws otherwise. */
function fromBase64(value: string): Uint8Array<ArrayBuffer> {
  if (!/^[A-Za-z0-9_+/-]*={0,2}$/.test(value) || value.length === 0) {
    throw new Error('not base64');
  }
  const b64 = value.replace(/-/g, '+').replace(/_/g, '/').replace(/=+$/, '');
  return Uint8Array.from(atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4)), (c) =>
    c.charCodeAt(0)
  );
}

const jsonPart = (part: string): unknown =>
  JSON.parse(new TextDecoder().decode(fromBase64(part)));

export async function createProofToken(payload: unknown, signer: ProofTokenSigner): Promise<string> {
  const header: ProofTokenHeader = {
    typ: 'askmi-poe',
    v: 2,
    alg: signer.key === 'hardware-passkey' ? 'webauthn-es256' : 'ES256',
    key: signer.key,
    kid: signer.kid,
    enc: 'base64url',
  };
  const signingInput = `${toBase64url(utf8.encode(canonicalStringify(header)))}.${toBase64url(
    utf8.encode(canonicalStringify(payload))
  )}`;

  const signaturePart =
    signer.key === 'hardware-passkey'
      ? toBase64url(utf8.encode(canonicalStringify(await signer.sign(signingInput))))
      : toBase64url(await signer.sign(signingInput));

  return `${signingInput}.${signaturePart}`;
}

/** The token header if it is a v2 proof token, otherwise null. */
export function decodeProofTokenHeader(token: string): ProofTokenHeader | null {
  try {
    const header = jsonPart(token.split('.')[0]) as Partial<ProofTokenHeader>;
    return header?.typ === 'askmi-poe' && header.v === 2 ? (header as ProofTokenHeader) : null;
  } catch {
    return null;
  }
}

/**
 * Verify a v2 proof token. Never throws. A hardware token needs the stored passkey
 * public key and the expected rpId; a software token needs the session public key.
 */
export async function verifyProofToken(
  token: string,
  opts: {
    publicKeyJwk?: JsonWebKey | null;
    expectedRpId?: string;
    expectedOrigin?: string;
    softwarePublicKey?: CryptoKey | null;
  }
): Promise<ProofTokenVerification> {
  const fail = (reason: ProofTokenFailure): ProofTokenVerification => ({ valid: false, reason });

  const parts = token.split('.');
  if (parts.length !== 3) return fail('MALFORMED');
  const [headerPart, payloadPart, signaturePart] = parts;

  let header: Partial<ProofTokenHeader>;
  let payload: unknown;
  try {
    header = jsonPart(headerPart) as Partial<ProofTokenHeader>;
    if (typeof header !== 'object' || header === null) return fail('MALFORMED');
  } catch {
    return fail('MALFORMED');
  }
  if (header.typ !== 'askmi-poe' || header.v !== 2) return fail('UNSUPPORTED_FORMAT');
  try {
    payload = jsonPart(payloadPart);
  } catch {
    return fail('MALFORMED');
  }

  const signingInput = `${headerPart}.${payloadPart}`;
  const ok = (): ProofTokenVerification => ({
    valid: true,
    header: header as ProofTokenHeader,
    payload,
  });

  if (header.key === 'hardware-passkey' && header.alg === 'webauthn-es256') {
    if (!isUsableP256Jwk(opts.publicKeyJwk)) return fail('NO_PUBLIC_KEY');
    if (!opts.expectedRpId) return fail('NO_EXPECTED_RP_ID');
    let assertion: IdentityAssertion;
    try {
      assertion = jsonPart(signaturePart) as IdentityAssertion;
    } catch {
      return fail('MALFORMED');
    }
    const result = await verifyIdentityAssertion({
      data: signingInput,
      assertion,
      publicKeyJwk: opts.publicKeyJwk,
      expectedRpId: opts.expectedRpId,
      expectedOrigin: opts.expectedOrigin,
    });
    return result.valid ? ok() : fail(result.reason);
  }

  if (header.key === 'software-session' && header.alg === 'ES256') {
    if (!opts.softwarePublicKey) return fail('NO_PUBLIC_KEY');
    let signature: Uint8Array<ArrayBuffer>;
    try {
      signature = fromBase64(signaturePart);
    } catch {
      return fail('MALFORMED');
    }
    if (signature.length !== 64) return fail('MALFORMED');
    const valid = await crypto.subtle.verify(
      { name: 'ECDSA', hash: 'SHA-256' },
      opts.softwarePublicKey,
      signature,
      utf8.encode(signingInput)
    );
    return valid ? ok() : fail('BAD_SIGNATURE');
  }

  return fail('UNSUPPORTED_FORMAT');
}

