import { describe, expect, it } from 'vitest';
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { isValidElementType } from 'react-is';
import * as qrModule from 'react-qr-code';

/**
 * Guard for the Vite 8 CommonJS interop change.
 *
 * react-qr-code is CommonJS (`exports.default = QRCode` with `__esModule`).
 * Under Vite 8 (Rolldown) a default import of it resolves to the whole
 * module object in the production bundle, so React gets an object instead
 * of a component (minified React error #130) and the page renders blank.
 * Vitest uses Node's interop and does not reproduce that, so this guard
 * pins the fix instead: use the named `QRCode` export.
 */
const componentsDir = __dirname;

describe('react-qr-code import', () => {
  it('is never a default import (breaks in the Vite 8 production bundle)', () => {
    const offenders = readdirSync(componentsDir)
      .filter((f) => /\.tsx?$/.test(f) && !f.includes('.test.'))
      .filter((f) =>
        /import\s+\w+\s+from\s+['"]react-qr-code['"]/.test(
          readFileSync(join(componentsDir, f), 'utf8')
        )
      );
    expect(offenders).toEqual([]);
  });

  it('exposes the named QRCode export as a React component', () => {
    expect(isValidElementType(qrModule.QRCode)).toBe(true);
  });
});

